fn review_action_toolbar_clause_draft(
    draft: &ActionToolbarClauseDraft,
    clause_kind: &str,
) -> Vec<String> {
    let mut findings = Vec::new();
    let trimmed = draft.clause.trim();
    if trimmed.is_empty() {
        findings.push("clause draft omitted the required `clause` field".into());
    }
    if trimmed.chars().count() > 100 {
        findings.push("clause draft was broader than the narrow microtask budget".into());
    }
    let lower = trimmed.to_ascii_lowercase();
    let placeholder_markers = [
        "placeholder",
        "todo",
        "example",
        "sample",
        "insert clause",
        "write clause",
    ];
    if placeholder_markers.iter().any(|marker| lower.contains(marker)) {
        findings.push("clause draft used placeholder wording instead of real UI copy".into());
    }
    if clause_kind == "run_action" && !(lower.contains("run") || lower.contains("start")) {
        findings.push("run-action clause draft did not mention running or starting the action".into());
    }
    if clause_kind == "clear_action" && !(lower.contains("clear") || lower.contains("reset") || lower.contains("fresh start")) {
        findings.push("clear-action clause draft did not mention clearing or resetting the action".into());
    }
    findings
}

fn parse_action_toolbar_clause_draft(raw: &str) -> Option<ActionToolbarClauseDraft> {
    let json = extract_first_json_object_local(raw)?;
    serde_json::from_str(&json).ok()
}

fn try_compose_toolbar_label_from_clause_drafts(
    clause_dir: &Path,
    project_name: &str,
) -> Option<String> {
    let base = sanitize_filename(project_name);
    let run_path = clause_dir.join(format!("{base}-run_action.json"));
    let clear_path = clause_dir.join(format!("{base}-clear_action.json"));
    let run_contents = fs::read_to_string(run_path).ok()?;
    let clear_contents = fs::read_to_string(clear_path).ok()?;
    let run_draft: ActionToolbarClauseDraft = serde_json::from_str(&run_contents).ok()?;
    let clear_draft: ActionToolbarClauseDraft = serde_json::from_str(&clear_contents).ok()?;
    let run_clause = run_draft.clause.trim().trim_end_matches('.').to_string();
    let clear_clause = clear_draft.clause.trim().trim_end_matches('.').to_string();
    if run_clause.is_empty() || clear_clause.is_empty() {
        return None;
    }
    Some(format!("{run_clause}. {clear_clause}."))
}

fn try_compose_metric_card_from_field_drafts(
    field_dir: &Path,
    project_name: &str,
) -> Option<MetricCardSemanticDraft> {
    let base = sanitize_filename(project_name);
    let title_path = field_dir.join(format!("{base}-title.json"));
    let value_path = field_dir.join(format!("{base}-value.json"));
    let context_path = field_dir.join(format!("{base}-context.json"));
    let title_contents = fs::read_to_string(title_path).ok()?;
    let value_contents = fs::read_to_string(value_path).ok()?;
    let context_contents = fs::read_to_string(context_path).ok()?;
    let title_draft: MetricCardFieldDraft = serde_json::from_str(&title_contents).ok()?;
    let value_draft: MetricCardFieldDraft = serde_json::from_str(&value_contents).ok()?;
    let context_draft: MetricCardFieldDraft = serde_json::from_str(&context_contents).ok()?;
    let title = title_draft.value.trim().to_string();
    let value = value_draft.value.trim().to_string();
    let context = context_draft.value.trim().to_string();
    if title.is_empty() || value.is_empty() || context.is_empty() {
        return None;
    }
    Some(MetricCardSemanticDraft {
        title,
        value,
        context,
    })
}

fn try_compose_metric_card_context_from_clause_drafts(
    clause_dir: &Path,
    project_name: &str,
) -> Option<String> {
    let base = sanitize_filename(project_name);
    let subject_path = clause_dir.join(format!("{base}-subject.json"));
    let purpose_path = clause_dir.join(format!("{base}-purpose.json"));
    let subject_contents = fs::read_to_string(subject_path).ok()?;
    let purpose_contents = fs::read_to_string(purpose_path).ok()?;
    let subject_draft: MetricCardFieldDraft = serde_json::from_str(&subject_contents).ok()?;
    let purpose_draft: MetricCardFieldDraft = serde_json::from_str(&purpose_contents).ok()?;
    let subject = subject_draft.value.trim().trim_end_matches('.').to_string();
    let purpose = purpose_draft.value.trim().to_string();
    if subject.is_empty() || purpose.is_empty() {
        return None;
    }
    let composed = if purpose.starts_with("for ") || purpose.starts_with("to ") {
        format!("{subject} {purpose}")
    } else {
        format!("{subject}. {purpose}")
    };
    Some(composed.trim().trim_end_matches('.').to_string() + ".")
}

