fn normalized_feature_slice_inputs(
    request: &RequestRecord,
    plan: &RequestPlan,
    inputs: &chatty_factory_core::ScaffoldInputs,
) -> Vec<String> {
    let lower = request.raw_request.to_ascii_lowercase();
    let mut features = request.requested_capabilities.clone();
    features.extend(plan.planner_suggested_features.clone());
    features.extend(inputs.feature_tokens.clone());
    features.extend(
        infer_chattycog_bridge_capabilities_from_text(&lower)
            .into_iter()
            .map(|capability| format!("bridge_{}", capability)),
    );
    features.retain(|feature| !feature.trim().is_empty());
    features.sort();
    features.dedup();
    features
}

fn derive_family_usage_summary(output_root: &Path) -> Result<FamilyUsageSummaryReceipt> {
    let projects = discover_projects(output_root, None)?;
    let mut family_counts: BTreeMap<String, FamilyUsageEntry> = BTreeMap::new();
    let mut ecosystem_project_counts: BTreeMap<String, usize> = BTreeMap::new();

    for project in projects {
        let Some(family_id) = project.family_id else {
            continue;
        };
        let family_key = family_id.as_str().to_string();
        let display_name = governance_family_display_name(&family_id);
        let ecosystem = governance_family_ecosystem(&family_id);
        let entry = family_counts
            .entry(family_key.clone())
            .or_insert_with(|| FamilyUsageEntry {
                family_id: family_key.clone(),
                family_display_name: display_name.clone(),
                family_ecosystem: ecosystem.clone(),
                project_count: 0,
            });
        entry.project_count += 1;
        if let Some(ecosystem) = ecosystem {
            *ecosystem_project_counts.entry(ecosystem).or_insert(0) += 1;
        }
    }

    let total_projects = family_counts.values().map(|entry| entry.project_count).sum();
    let mut families = family_counts.into_values().collect::<Vec<_>>();
    families.sort_by(|left, right| {
        right
            .project_count
            .cmp(&left.project_count)
            .then_with(|| left.family_display_name.cmp(&right.family_display_name))
    });

    Ok(FamilyUsageSummaryReceipt {
        summary_id: chatty_factory_core::timestamp_id("family-usage-summary"),
        total_projects,
        ecosystem_project_counts,
        families,
        updated_at: chatty_factory_core::timestamp_id("updated"),
    })
}

fn derive_starter_usage_summary(runtime_root: &Path) -> Result<StarterUsageSummaryReceipt> {
    let receipts_dir = runtime_root.join("build_receipts");
    let Ok(entries) = fs::read_dir(receipts_dir) else {
        return Ok(StarterUsageSummaryReceipt {
            summary_id: chatty_factory_core::timestamp_id("starter-usage-summary"),
            total_build_receipts: 0,
            explicit_override_builds: 0,
            auto_routed_builds: 0,
            matched_recommendation_builds: 0,
            overridden_recommendation_builds: 0,
            starters: Vec::new(),
            updated_at: chatty_factory_core::timestamp_id("updated"),
        });
    };

    let mut starter_counts: BTreeMap<String, StarterUsageEntry> = BTreeMap::new();
    let mut total_build_receipts = 0usize;
    let mut explicit_override_builds = 0usize;
    let mut auto_routed_builds = 0usize;
    let mut matched_recommendation_builds = 0usize;
    let mut overridden_recommendation_builds = 0usize;

    for entry in entries {
        let entry = entry?;
        if !entry.file_type()?.is_file() {
            continue;
        }
        let contents = match fs::read_to_string(entry.path()) {
            Ok(contents) => contents,
            Err(_) => continue,
        };
        let receipt = match serde_json::from_str::<chatty_factory_core::BuildReceipt>(&contents) {
            Ok(receipt) => receipt,
            Err(_) => continue,
        };
        total_build_receipts += 1;
        match receipt.starter_recommendation_comparison.as_deref() {
            Some("matched_normal_routing") | Some("auto_followed_normal_routing") => {
                matched_recommendation_builds += 1;
            }
            Some("overrode_normal_routing") => {
                overridden_recommendation_builds += 1;
            }
            _ => {}
        }
        let starter_id = if let Some(starter_id) = receipt.starter_override_id {
            explicit_override_builds += 1;
            starter_id
        } else {
            auto_routed_builds += 1;
            "auto".to_string()
        };
        let entry = starter_counts
            .entry(starter_id.clone())
            .or_insert_with(|| StarterUsageEntry {
                starter_id: starter_id.clone(),
                starter_label: build_starter_label(&starter_id).to_string(),
                starter_lifecycle: build_starter_lifecycle(&starter_id).to_string(),
                build_count: 0,
            });
        entry.build_count += 1;
    }

    let mut starters = starter_counts.into_values().collect::<Vec<_>>();
    starters.sort_by(|left, right| {
        right
            .build_count
            .cmp(&left.build_count)
            .then_with(|| left.starter_label.cmp(&right.starter_label))
    });

    Ok(StarterUsageSummaryReceipt {
        summary_id: chatty_factory_core::timestamp_id("starter-usage-summary"),
        total_build_receipts,
        explicit_override_builds,
        auto_routed_builds,
        matched_recommendation_builds,
        overridden_recommendation_builds,
        starters,
        updated_at: chatty_factory_core::timestamp_id("updated"),
    })
}

fn derive_triangulation_loop_summary(runtime_root: &Path) -> Result<TriangulationLoopSummaryReceipt> {
    #[derive(Debug, Clone)]
    struct ModelLadderExhaustionEvidence {
        task_label: String,
        posture: String,
        attempted_models: Vec<String>,
    }

    let load_sorted_paths = |dir_name: &str| -> Vec<PathBuf> {
        let dir = runtime_root.join(dir_name);
        let Ok(entries) = fs::read_dir(dir) else {
            return Vec::new();
        };
        let mut paths = entries
            .flatten()
            .filter_map(|entry| {
                let modified = entry.metadata().ok()?.modified().ok()?;
                Some((modified, entry.path()))
            })
            .collect::<Vec<_>>();
        paths.sort_by(|left, right| right.0.cmp(&left.0));
        paths.into_iter().map(|(_, path)| path).collect()
    };

    let floor_paths = load_sorted_paths("atomization_floor_decisions");
    let vault_paths = load_sorted_paths("failure_vault");
    let session_paths = load_sorted_paths("triangulation_sessions");
    let candidate_paths = load_sorted_paths("constraint_promotion_candidates");
    let model_attempt_paths = load_sorted_paths("model_task_attempts");

    let latest_floor = floor_paths
        .first()
        .and_then(|path| fs::read_to_string(path).ok())
        .and_then(|contents| serde_json::from_str::<AtomizationFloorDecision>(&contents).ok());
    let sessions = session_paths
        .iter()
        .filter_map(|path| fs::read_to_string(path).ok())
        .filter_map(|contents| serde_json::from_str::<TriangulationSession>(&contents).ok())
        .collect::<Vec<_>>();
    let vault_entries = vault_paths
        .iter()
        .filter_map(|path| fs::read_to_string(path).ok())
        .filter_map(|contents| serde_json::from_str::<FailureVaultEntry>(&contents).ok())
        .collect::<Vec<_>>();
    let model_attempts = model_attempt_paths
        .iter()
        .filter_map(|path| fs::read_to_string(path).ok())
        .filter_map(|contents| serde_json::from_str::<PlanTaskModelAttemptReceipt>(&contents).ok())
        .collect::<Vec<_>>();
    let latest_candidate = candidate_paths
        .first()
        .and_then(|path| fs::read_to_string(path).ok())
        .and_then(|contents| serde_json::from_str::<ConstraintPromotionCandidate>(&contents).ok());

    let model_ladder_evidence = model_attempts
        .iter()
        .filter_map(|attempt| {
            let attempted_models = attempt
                .review_findings
                .iter()
                .find_map(|finding| {
                    finding
                        .strip_prefix("attempted models: ")
                        .map(|value| {
                            value
                                .split(", ")
                                .map(str::trim)
                                .filter(|item| !item.is_empty())
                                .map(str::to_string)
                                .collect::<Vec<_>>()
                        })
                })
                .unwrap_or_default();
            let current_model_exhausted = attempt.review_findings.iter().any(|finding| {
                finding.starts_with(
                    "alternate methods exhausted for current model; escalating retry search to next model candidate:"
                )
            });
            let full_ladder_exhausted = attempt.status == "method_space_exhausted"
                || attempt.review_findings.iter().any(|finding| {
                    finding.starts_with(
                        "alternate methods exhausted across the available model/runtime candidates"
                    )
                });

            let posture = if full_ladder_exhausted {
                Some("full_model_ladder_exhausted")
            } else if current_model_exhausted {
                Some("current_model_only_exhausted")
            } else {
                None
            }?;

            Some(ModelLadderExhaustionEvidence {
                task_label: attempt.task_id.clone(),
                posture: posture.into(),
                attempted_models,
            })
        })
        .collect::<Vec<_>>();

    let current_model_only_exhaustion_count = model_ladder_evidence
        .iter()
        .filter(|entry| entry.posture == "current_model_only_exhausted")
        .count();
    let full_model_ladder_exhaustion_count = model_ladder_evidence
        .iter()
        .filter(|entry| entry.posture == "full_model_ladder_exhausted")
        .count();
    let latest_model_ladder = model_ladder_evidence.first();

    let latest_candidate_proposal_path = latest_candidate.as_ref().and_then(|candidate| {
        let dir = runtime_root.join("proposed_constraint_receipts");
        let Ok(entries) = fs::read_dir(dir) else {
            return None;
        };
        entries.flatten().find_map(|entry| {
            let path = entry.path();
            let contents = fs::read_to_string(&path).ok()?;
            let receipt = serde_json::from_str::<ProposedConstraintReceipt>(&contents).ok()?;
            if receipt.source_verification_id == candidate.triangulation_session_id {
                Some(path.display().to_string())
            } else {
                None
            }
        })
    });

    Ok(TriangulationLoopSummaryReceipt {
        summary_id: chatty_factory_core::timestamp_id("triangulation-loop-summary"),
        open_provisional_vault_entries: vault_entries
            .iter()
            .filter(|entry| entry.status == "provisional_open")
            .count(),
        triangulation_session_count: sessions.len(),
        floor_level_convergent_failures: sessions
            .iter()
            .filter(|session| {
                session.convergence_posture == "repeated_convergent_failure"
                    && !session.successful_alternate_method
            })
            .count(),
        pending_promotion_candidates: candidate_paths.len(),
        current_model_only_exhaustion_count,
        full_model_ladder_exhaustion_count,
        latest_floor_task_label: latest_floor.as_ref().map(|decision| {
            decision
                .task_subtype
                .clone()
                .unwrap_or_else(|| decision.task_id.clone())
        }),
        latest_floor_granularity: latest_floor
            .as_ref()
            .map(|decision| decision.current_granularity.clone()),
        latest_floor_decision: latest_floor
            .as_ref()
            .map(|decision| decision.decision.clone()),
        latest_session_label: sessions.first().map(|session| {
            session
                .task_subtype
                .clone()
                .unwrap_or_else(|| session.task_lineage_key.clone())
        }),
        latest_session_convergence_posture: sessions
            .first()
            .map(|session| session.convergence_posture.clone()),
        latest_candidate_label: latest_candidate.as_ref().map(|candidate| {
            candidate
                .task_subtype
                .clone()
                .unwrap_or_else(|| candidate.candidate_id.clone())
        }),
        latest_candidate_confidence_posture: latest_candidate
            .as_ref()
            .map(|candidate| candidate.confidence_posture.clone()),
        latest_candidate_proposal_path,
        latest_model_ladder_task_label: latest_model_ladder.map(|entry| entry.task_label.clone()),
        latest_model_ladder_posture: latest_model_ladder.map(|entry| entry.posture.clone()),
        latest_model_ladder_attempted_models: latest_model_ladder
            .map(|entry| entry.attempted_models.clone())
            .unwrap_or_default(),
        updated_at: chatty_factory_core::timestamp_id("updated"),
    })
}

